import * as D from './domain.js';
import * as Repo from './repository.js';
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = (ms, opts = {}) => new Intl.DateTimeFormat('pt-BR', { timeZone: D.POLICY.zone, day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', ...opts }).format(ms);
const dateLabel = date => new Intl.DateTimeFormat('pt-BR', { timeZone: D.POLICY.zone, day: '2-digit', month: 'short' }).format(Date.parse(date + 'T12:00:00-03:00'));
const money = value => value === null ? 'Não informado' : new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
const roles = { owner: 'Dono(a)', manager: 'Gestão', promoter: 'Promotor', media: 'Mídia' };
const statusLabels = { confirmed: 'Confirmado', invited: 'Aguardando confirmação', expired: 'Convocação expirada', declined: 'Recusado', replaced: 'Substituído', changed: 'Alteração · reconfirmar', published: 'Publicado', draft: 'Rascunho', cancelled: 'Cancelado' };
const badge = (label, type = '') => `<span class="badge ${type}">${esc(label)}</span>`;
const personName = id => state.people.find(p => p.id === id)?.name || 'Pessoa';
const eventName = id => D.getEvent(state, id).title;
const operational = () => actor && D.OPERATORS.includes(actor.role);
let state, actor, page = 'agenda', selectedEvent = null;
let filter = { from: '2026-11-18', to: '2026-11-18', start: '00:00', end: '23:59', person: '', status: '' };
let metricPeriod = 'week';
try { state = Repo.load(); actor = state.people.find(p => p.id === sessionStorage.getItem('retratus.actor') && p.approved) || state.people[0]; }
catch (error) { $('#app').innerHTML = `<main class="fatal"><h1>Não foi possível carregar a demonstração</h1><p>${esc(error.message)}</p><button id="recover">Restaurar demonstração</button></main>`; $('#recover').onclick = () => { Repo.reset(); location.reload(); }; }
function toast(message, error = false) { const el = $('#toast'); el.textContent = message; el.className = `visible ${error ? 'error' : ''}`; if (error && $('#modal').open) { let alert = $('#modal .form-error'); if (!alert) { alert = document.createElement('p'); alert.className = 'form-error warning'; alert.setAttribute('role', 'alert'); $('#modal .modal-header').after(alert); } alert.textContent = message; alert.scrollIntoView({ block: 'nearest' }); } clearTimeout(toast.timer); toast.timer = setTimeout(() => el.className = '', 6500); }
function mutate(action, message = 'Alteração salva.') {
  try { state = Repo.transact(state, action); actor = state.people.find(p => p.id === actor?.id) || actor; render(); toast(message); return true; }
  catch (error) { toast(error.message, true); return false; }
}
function modal(title, body) { $('#modal').innerHTML = `<header class="modal-header"><h2 id="modal-title">${title}</h2><button type="button" class="icon-button" data-action="close" aria-label="Fechar">×</button></header>${body}`; $('#modal').showModal(); }
function close() { $('#modal').close(); }
function field(label, control, extra = '') { return `<label class="field ${extra}"><span>${label}</span>${control}</label>`; }
function input(name, value = '', type = 'text', attrs = '') { return `<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`; }
function actions(submit = 'Salvar') { return `<footer class="form-actions"><button type="button" class="secondary" data-action="close">Voltar</button><button type="submit">${submit}</button></footer>`; }
function empty(title, text) { return `<div class="empty"><h3>${title}</h3><p>${text}</p></div>`; }
function limits() { modal('Sobre a demonstração', `<div class="modal-body prose"><p><strong>Todos os nomes, telefones, trabalhos, imagens e valores são fictícios.</strong> As contas são simulações de perfis, com senha <code>demo123</code>.</p><p>Os dados e as fotos ficam somente neste navegador. Não há autenticação segura, servidor de negócio ou compartilhamento entre dispositivos. Qualquer pessoa com acesso ao navegador pode inspecionar a base completa. Não insira dados reais.</p><p>O relógio da demonstração começa em 18/11/2026, às 10h, em Belém. Avance-o para testar encerramentos e expirações. As regras são reaplicadas ao carregar e alterar a base, mas não há tarefa em segundo plano.</p><p>Fotos: JPG, PNG ou WebP, até 1 MB por arquivo, sujeitas à pequena quota do navegador. A simulação remove o conteúdo da foto após 30 dias do encerramento e preserva os registros operacionais. Cópias previamente baixadas não são apagadas.</p><p>Produção exige autenticação por telefone e senha, permissões no servidor, arquivos privados, banco compartilhado, tarefas confiáveis de expiração e exclusão e política de recuperação de acesso. Nenhuma conta ou infraestrutura externa foi criada.</p><p>Valores são apenas <strong>valores informados</strong>, sem controle de pagamento. A soma não representa o custo total de um evento.</p></div>`); }
function navItems() { return operational() ? [['agenda', 'Agenda da equipe'], ['events', 'Eventos e Ações'], ['review', 'Conferência'], ['metrics', 'Distribuição'], ['team', 'Equipe'], ['photos', 'Registros fotográficos'], ['history', 'Histórico']] : actor.role === 'media' ? [['events', 'Eventos e Ações'], ['photos', 'Registros fotográficos']] : [['opportunities', 'Oportunidades'], ['mine', 'Meus compromissos'], ['photos', 'Minhas fotos']]; }
function render() {
  if (!actor) { loginScreen(); return; }
  if (!navItems().some(n => n[0] === page)) page = navItems()[0][0];
  const titles = { agenda: ['Visão da operação', 'Agenda da equipe', 'Escalas e confirmações por pessoa, data e horário.'], events: ['Planejamento', 'Eventos e Ações', 'Cadastro de eventos, ações, serviços e vagas.'], opportunities: ['Seu próximo trabalho', 'Oportunidades', 'Escolha os serviços aos quais deseja se candidatar.'], mine: ['Sua agenda', 'Meus compromissos', 'Suas convocações e participações.'], review: ['Após o evento', 'Conferência de trabalhos', 'Trabalhos encerrados e horários para conferência.'], metrics: ['Visão da gestão', 'Distribuição de oportunidades', 'Eventos realizados, dias de ação e horas por freelancer.'], team: ['Pessoas', 'Equipe e acessos', 'Cadastros, aprovação e vínculo interno.'], photos: ['Memória da operação', actor.role === 'promoter' ? 'Minhas fotos' : 'Registros fotográficos', 'Registros de início e fim · retenção de 30 dias após o encerramento.'], history: ['Rastreabilidade', 'Histórico operacional', 'Registro de alterações, substituições e cancelamentos.'] };
  const title = titles[page];
  $('#app').innerHTML = `<div class="demo-banner"><span>DEMONSTRAÇÃO <span class="desktop-inline">· Dados e contas fictícios</span></span><button data-action="limits">Sobre a demonstração</button></div>
  <aside class="sidebar"><a class="brand" href="#" data-action="home"><img class="brand-logo" src="/src/assets/retratus-dark.png" alt="Retratus"></a><div class="brand-caption">EQUIPE & ESCALAS</div><div class="workspace"><div><strong>Operação Retratus</strong><small>Pará · Brasil</small></div></div><nav>${navItems().map(([id, label]) => `<button class="nav-item ${page === id ? 'selected' : ''}" data-page="${id}">${label}${id === 'review' && state.records.some(r => r.closedAt && r.review === 'pending') ? '<span class="nav-dot"></span>' : ''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="zone"><div>Horário da operação<small>America/Belem · UTC−3</small></div></div><button class="profile" data-action="accounts"><span class="avatar">${actor.role === 'owner' ? 'DO' : actor.role === 'manager' ? 'GE' : actor.role === 'media' ? 'MI' : esc(actor.name.slice(9, 11))}</span><span><strong>${esc(actor.name)}</strong><small>${roles[actor.role]} · acesso simulado</small></span><span class="profile-switch">Trocar conta</span></button></div></aside>
  <div class="main-shell"><header class="topbar"><div class="breadcrumb">Retratus <span>/</span> ${title[1]}</div><button class="clock-button" data-action="clock"><span>Relógio demo <strong>${fmt(state.now)}</strong></span></button></header><main><div class="page-heading"><div><h1>${title[1]}</h1><p class="subtitle">${title[2]}</p></div>${operational() ? '<button data-action="new-event">Novo Evento ou Ação</button>' : '<button class="secondary" data-action="accounts">Trocar conta demo</button>'}</div><div id="page-content">${pageContent()}</div><footer class="page-footer"><span>Retratus · Equipe e escalas</span><button data-action="limits">Demonstração local · dados fictícios</button></footer></main></div>`;
}
function pageContent() { return ({ agenda, events: eventList, opportunities: eventList, mine, review, metrics: metricView, team, photos, history })[page](); }
function range() { return { start: Date.parse(`${filter.from}T${filter.start}:00-03:00`), end: Date.parse(`${filter.to}T${filter.end}:59-03:00`) }; }
function inRange(day) { return D.overlaps(D.interval(day), range()); }
function relevantAssignments(personId) { return state.assignments.filter(a => a.personId === personId && D.active(state, a) && D.assignmentDays(state, a).some(inRange)); }
function agenda() {
  const people = state.people.filter(p => p.role === 'promoter' && p.approved && (!filter.person || p.id === filter.person));
  const confirmed = people.filter(p => relevantAssignments(p.id).some(a => a.status === 'confirmed'));
  const waiting = people.filter(p => relevantAssignments(p.id).some(a => a.status === 'invited'));
  const unassigned = people.filter(p => !relevantAssignments(p.id).length);
  const openEvents = state.events.filter(e => e.status === 'published' && e.days.some(d => inRange(d) && D.interval(d).start > state.now && e.services.some(s => D.freeSlots(state, e, s.name, d.id) > 0)));
  const risks = people.filter(p => { const rows = relevantAssignments(p.id); return rows.some((a, i) => rows.slice(i + 1).some(b => D.assignmentDays(state, a).some(d => inRange(d) && D.assignmentDays(state, b).some(o => D.overlaps(D.interval(d), D.interval(o)))))); });
  const shown = people.filter(p => !filter.status || (filter.status === 'confirmed' ? confirmed : filter.status === 'invited' ? waiting : unassigned).includes(p));
  return `<div class="stats-grid">${stat('Com escala confirmada', confirmed.length, 'No período consultado', 'green')}${stat('Aguardando confirmação', waiting.length, 'Convocações ainda válidas', 'amber')}${stat('Sem escala registrada', unassigned.length, 'Disponibilidade a consultar', 'neutral')}${stat('Trabalhos com vagas', openEvents.length, 'Seleção manual pela gestão', 'purple')}</div>
  <section class="panel agenda-panel"><header class="panel-heading"><div><h2>Escalas no período</h2><p>Filtre por data, horário ou pessoa.</p></div><span class="pill">${people.length} pessoas</span></header><form id="filter-form" class="filters">${field('De', input('from', filter.from, 'date', 'required'))}${field('Até', input('to', filter.to, 'date', 'required'))}${field('Início', input('start', filter.start, 'time', 'required'))}${field('Fim', input('end', filter.end, 'time', 'required'))}${field('Pessoa', `<select name="person"><option value="">Toda a equipe</option>${state.people.filter(p => p.role === 'promoter' && p.approved).map(p => `<option value="${p.id}" ${filter.person === p.id ? 'selected' : ''}>${esc(p.name)}</option>`).join('')}</select>`)}<button type="submit" class="secondary">Consultar</button></form>
  <div class="agenda-toolbar"><div class="tabs">${[['', 'Todos'], ['confirmed', 'Confirmados'], ['invited', 'Aguardando'], ['free', 'Sem escala']].map(([id, label]) => `<button data-status="${id}" class="${filter.status === id ? 'active' : ''}">${label}</button>`).join('')}</div><span class="date-caption">${dateLabel(filter.from)}${filter.from !== filter.to ? ' — ' + dateLabel(filter.to) : ''}</span></div>
  <div class="agenda-note"><p><strong>Sem escala registrada não significa disponibilidade confirmada.</strong> Consulte a pessoa antes de escalá-la.</p></div>
  ${risks.length ? `<div class="warning">${risks.length} pessoa(s) com sobreposição de convocações ou escala. A confirmação será revalidada: ${risks.map(p => esc(p.name)).join(', ')}.</div>` : ''}
  <div class="agenda-table"><div class="agenda-columns"><span>PROFISSIONAL</span><span>OCUPAÇÃO NO PERÍODO <small>Horário de Belém</small></span><span>SITUAÇÃO</span></div>${shown.length ? shown.map(p => personRow(p)).join('') : empty('Nenhuma pessoa neste filtro', 'Altere os filtros para consultar a equipe.')}</div><div class="panel-bottom"><span class="legend-dot green"></span> Confirmado <span class="legend-dot amber"></span> Aguardando <span class="legend-dot gray"></span> Sem escala <span class="push">${shown.length} pessoas exibidas</span></div></section>
  <section class="open-work"><div class="section-heading"><h2>Vagas abertas</h2><button class="text-button" data-page="events">Ver Eventos e Ações</button></div><div class="event-grid">${openEvents.length ? openEvents.slice(0, 3).map(eventCard).join('') : empty('Nenhuma vaga aberta', 'Nenhuma vaga futura aberta no período consultado.')}</div></section>`;
}
function stat(label, value, detail, tone) { return `<article class="stat ${tone}"><div><span>${label}</span></div><strong>${value.toString().padStart(2, '0')}</strong><p>${detail}</p></article>`; }
function personRow(p) {
  const rows = relevantAssignments(p.id);
  return `<div class="person-row"><div class="person-cell"><span class="avatar ${p.link !== 'freelancer' ? 'staff' : ''}">${esc(p.name.match(/\d+/)?.[0] || 'EQ')}</span><div><strong>${esc(p.name.replace(' · Demo', ''))}</strong><small>${({ freelancer: 'Freelancer', employee: 'Funcionário', provider: 'Prestador', unclassified: 'Vínculo não classificado' })[p.link]} · fictício</small></div></div><div class="occupations">${rows.length ? rows.map(a => `<button class="occupation ${a.status}" data-event="${a.eventId}"><span class="occupation-line"><strong>${esc(eventName(a.eventId))}</strong><b>${esc(a.service)}</b></span><span>${D.assignmentDays(state, a).filter(inRange).map(d => `${dateLabel(d.date)} · ${d.start}–${d.end}${d.end < d.start ? ' (+1 dia)' : ''}`).join(' / ')}</span>${a.status === 'invited' ? `<small>Responder até ${fmt(a.deadline)}</small>` : ''}</button>`).join('') : '<div class="no-schedule">Nenhuma escala neste período</div>'}</div><div class="person-status">${rows.some(a => a.status === 'confirmed') ? badge('Confirmado', 'confirmed') : rows.length ? badge('Aguardando', 'invited') : badge('Consultar disponibilidade', 'neutral')}</div></div>`;
}
function eventCard(e) {
  const upcoming = e.days.filter(d => D.interval(d).start > state.now);
  const open = upcoming.reduce((n, d) => n + e.services.reduce((v, s) => v + Math.max(0, D.freeSlots(state, e, s.name, d.id)), 0), 0);
  const day = e.days[0];
  return `<article class="event-card"><div class="card-top">${badge(D.ACTIVITY_TYPES[e.type], e.type === 'action' ? 'purple' : 'neutral')}${e.status !== 'published' ? badge(statusLabels[e.status], e.status) : `<span class="card-meta">${esc(e.city)}</span>`}</div><button class="event-title" data-event="${e.id}">${esc(e.title)}</button><p class="card-date">${dateLabel(day.date)}${e.days.length > 1 ? ' — ' + dateLabel(e.days.at(-1).date) : ''} <span>·</span> ${day.start}–${day.end}${day.end < day.start ? ' (+1 dia)' : ''}</p><p class="location">${esc(e.location)}</p><div class="service-tags">${e.services.map(s => `<span>${esc(s.name)}</span>`).join('')}</div><div class="card-bottom"><span>${e.status === 'cancelled' ? 'Cancelamento registrado' : e.status === 'draft' ? 'Aguardando publicação' : open ? `${open} ${e.type === 'action' ? 'vaga(s)/dia' : 'vaga(s)'} em aberto` : 'Sem vagas futuras'}</span><button class="text-button" data-event="${e.id}">Detalhes</button></div></article>`;
}
function eventList() {
  if (selectedEvent) return eventDetail(D.getEvent(state, selectedEvent));
  const events = state.events.filter(e => operational() || e.status !== 'draft');
  return `<div class="info-line">${page === 'opportunities' ? 'Todas as pessoas aprovadas podem se candidatar. Candidaturas encerram 24h antes do primeiro início; valores são negociados por contato direto.' : 'Eventos e Ações com horários diários. Abra um trabalho para consultar a escala e os registros.'}</div><div class="event-grid">${events.map(eventCard).join('')}</div>`;
}
function eventDetail(e) {
  const assignments = state.assignments.filter(a => a.eventId === e.id && (operational() || actor.role === 'media' || a.personId === actor.id));
  const ownApp = state.applications.find(a => a.eventId === e.id && a.personId === actor.id);
  const apps = operational() ? state.applications.filter(a => a.eventId === e.id) : [];
  return `<button class="back-link" data-action="back-events">Todos os Eventos e Ações</button><section class="panel detail"><div class="detail-title"><div>${badge(D.ACTIVITY_TYPES[e.type])}${badge(statusLabels[e.status], e.status)}<h2>${esc(e.title)}</h2><p>${esc(e.location)} · ${esc(e.city)}</p></div>${operational() && e.status !== 'cancelled' ? `<div class="button-row"><button class="secondary" data-edit="${e.id}">Editar</button>${e.status === 'draft' ? `<button data-publish="${e.id}">Publicar</button>` : `<button data-invite="${e.id}">Convocar pessoa</button>`}</div>` : ''}</div><p>${esc(e.notes)}</p>${operational() && e.preference ? `<p class="info-line"><strong>Preferência do cliente:</strong> ${esc(e.preference)}</p>` : ''}${e.cancelReason ? `<p class="warning">${esc(e.cancelReason)}</p>` : ''}<div class="service-tags">${e.services.map(s => `<span>${s.name} · ${s.capacity} vaga(s) por dia</span>`).join('')}</div><details ${e.days.length === 1 ? 'open' : ''}><summary>Programação diária · ${e.days.length} dia(s)</summary><div class="day-grid">${e.days.map(d => `<div><strong>${dateLabel(d.date)}</strong><span>${d.start}–${d.end}${d.end < d.start ? ' (+1 dia)' : ''}</span><small>${e.services.map(s => `${s.name}: ${Math.max(0, D.freeSlots(state, e, s.name, d.id))} livre(s)`).join(' · ')}</small></div>`).join('')}</div></details>${actor.role === 'promoter' && e.status === 'published' ? `<div class="info-line">${ownApp ? `Interesse registrado: ${ownApp.services.map(esc).join(', ')}. ` : ''}Candidaturas até ${fmt(D.eventStart(e) - D.POLICY.applicationHours * D.HOUR)}.</div><button data-apply="${e.id}" ${state.now >= D.eventStart(e) - D.POLICY.applicationHours * D.HOUR ? 'disabled' : ''}>Manifestar interesse</button>` : ''}</section>
  ${operational() ? `<section class="panel detail"><h2>Candidaturas · ${apps.length}</h2><p class="muted">Candidaturas recebidas. A seleção é feita pela gestão.</p>${apps.length ? apps.map(a => { const conflict = D.conflicts(state, a.personId, e.days); return `<div class="list-row"><div><strong>${esc(personName(a.personId))}</strong><p>${a.services.map(esc).join(' · ')}</p>${conflict.length ? badge('Conflito com escala confirmada', 'danger') : ''}</div>${e.status === 'published' ? `<button class="secondary" data-candidate="${a.personId}" data-event-id="${e.id}">Selecionar manualmente</button>` : ''}</div>`; }).join('') : empty('Sem candidaturas', 'A gestão também pode convocar alguém diretamente.')}</section>` : ''}
  <section class="panel detail"><h2>${actor.role === 'promoter' ? 'Sua participação' : 'Participações e convocações'}</h2>${assignments.length ? assignments.map(assignmentCard).join('') : empty('Nenhuma participação registrada', 'As convocações aparecerão aqui.')}</section>${operational() && e.status !== 'cancelled' ? `<button class="danger-button" data-cancel="${e.id}">Cancelar trabalho com motivo</button>` : ''}`;
}
function assignmentCard(a) {
  const days = D.assignmentDays(state, a), e = D.getEvent(state, a.eventId);
  return `<div class="assignment"><div class="list-row"><div><strong>${esc(personName(a.personId))}</strong><p>${esc(e.title)} · ${esc(a.service)}</p></div>${badge(e.status === 'cancelled' ? 'Trabalho cancelado' : statusLabels[a.status], e.status === 'cancelled' ? 'cancelled' : a.status)}</div><p class="muted">${days.length} dia(s): ${days.slice(0, 3).map(d => `${dateLabel(d.date)}, ${d.start}–${d.end}${d.end < d.start ? ' (+1 dia)' : ''}`).join(' / ')}${days.length > 3 ? ` e mais ${days.length - 3}` : ''}</p>${a.reason ? `<p class="warning">${esc(a.reason)}</p>` : ''}${a.status === 'invited' && e.status === 'published' ? `<p class="deadline">Responder até ${fmt(a.deadline)} · ${Math.max(0, Math.ceil((a.deadline - state.now) / D.HOUR))}h restantes</p>${D.conflicts(state, a.personId, days, a.id).length ? '<p class="warning">Conflito com outra participação confirmada. Não será possível confirmar.</p>' : ''}${actor.id === a.personId ? `<div class="button-row"><button data-respond="${a.id}" data-accept="true">Confirmar convocação</button><button class="secondary" data-respond="${a.id}" data-accept="false">Recusar</button></div>` : ''}` : ''}
  ${operational() && D.active(state, a) ? `<button class="text-button" data-release="${a.id}">Substituir / remover dias</button>` : ''}
  ${actor.id === a.personId && a.status === 'confirmed' && e.status === 'published' ? `<details open><summary>Registros por dia</summary><div class="daily-records">${days.map(d => { const r = state.records.find(r => r.assignmentId === a.id && r.dayId === d.id); return `<div class="daily-row"><span><strong>${dateLabel(d.date)}</strong> · ${d.start}–${d.end}</span>${r?.closedAt ? badge(r.review === 'reviewed' ? 'Realizado · conferido' : 'Realizado · pendente de conferência', 'confirmed') : `<button class="secondary small" data-upload="${a.id}" data-day="${d.id}" data-kind="${r ? 'end' : 'start'}">${r ? 'Enviar foto final e encerrar' : 'Enviar foto de início'}</button>`}</div>`; }).join('')}</div></details>` : ''}</div>`;
}
function mine() {
  const list = state.assignments.filter(a => a.personId === actor.id);
  return `<div class="info-line">O envio da foto final encerra apenas a sua participação daquele dia, inclusive após a meia-noite. A conferência administrativa ocorre depois.</div><section class="panel detail">${list.length ? list.map(assignmentCard).join('') : empty('Nenhum compromisso registrado', 'Consulte oportunidades ou aguarde uma convocação.')}</section><section class="panel detail"><h2>Seus interesses registrados</h2>${state.applications.filter(a => a.personId === actor.id).map(a => `<div class="list-row"><div><strong>${esc(eventName(a.eventId))}</strong><p>${a.services.map(esc).join(' · ')}</p></div><button data-event="${a.eventId}" class="secondary">Abrir trabalho</button></div>`).join('') || '<p class="muted">Você ainda não se candidatou.</p>'}</section>`;
}
function review() {
  return `<div class="info-line">Horários previstos, envios e horários validados ficam separados. Uma foto não comprova automaticamente a duração trabalhada.</div><section class="panel detail">${state.records.filter(r => r.closedAt).map(r => { const a = D.getAssignment(state, r.assignmentId); return `<article class="review-card"><div class="list-row"><div><h3>${esc(eventName(a.eventId))}</h3><p>${esc(personName(a.personId))} · ${esc(a.service)}</p></div>${badge(r.review === 'reviewed' ? 'Conferido' : 'Pendente de conferência', r.review === 'reviewed' ? 'confirmed' : 'invited')}</div><div class="record-times"><div><small>PREVISTO</small>${fmt(r.planned.start)} → ${fmt(r.planned.end)}</div><div><small>ENVIO DAS FOTOS</small>${fmt(r.startPhoto.sentAt)} → ${fmt(r.endPhoto.sentAt)}</div><div><small>VALIDADO PELA GESTÃO</small>${r.validatedStart ? `${fmt(r.validatedStart)} → ${fmt(r.validatedEnd)}` : 'Ainda não conferido'}</div></div>${r.reviewNote ? `<p class="muted">${esc(r.reviewNote)}</p>` : ''}<div class="button-row"><button class="secondary" data-review="${r.id}">Conferir / corrigir horários</button>${actor.role === 'owner' ? `<button class="secondary" data-amount="${r.id}">Valor informado: ${money(r.amount)}</button>` : ''}</div></article>`; }).join('') || empty('Nenhum trabalho encerrado', 'Os registros aparecerão após o envio da foto final.')}</section>`;
}
function metricRange() {
  const date = new Date(D.localDate(state.now) + 'T12:00:00-03:00');
  if (metricPeriod === 'month') { const year = date.getUTCFullYear(), month = date.getUTCMonth(); return { start: Date.parse(`${year}-${String(month + 1).padStart(2, '0')}-01T00:00:00-03:00`), end: Date.parse(new Date(Date.UTC(year, month + 1, 1)).toISOString().slice(0, 10) + 'T00:00:00-03:00') }; }
  const offset = (date.getUTCDay() - D.POLICY.weekStartsOn + 7) % 7, start = Date.parse(D.localDate(state.now - offset * D.DAY) + 'T00:00:00-03:00'); return { start, end: start + 7 * D.DAY };
}
function metricView() {
  const period = metricRange(), rows = D.metrics(state, actor, period.start, period.end);
  const waiting = state.assignments.filter(a => a.status === 'invited' && D.active(state, a) && D.assignmentDays(state, a).some(d => D.overlaps(D.interval(d), period))).length;
  const applications = state.applications.filter(a => { const e = D.getEvent(state, a.eventId); return e.status === 'published' && e.days.some(d => D.overlaps(D.interval(d), period)) && !state.assignments.some(s => s.eventId === a.eventId && s.personId === a.personId && D.active(state, s)); }).length;
  const slots = state.events.filter(e => e.status === 'published').reduce((n, e) => n + e.days.filter(d => D.overlaps(D.interval(d), period) && D.interval(d).start > state.now).reduce((v, d) => v + e.services.reduce((w, s) => w + Math.max(0, D.freeSlots(state, e, s.name, d.id)), 0), 0), 0);
  return `<div class="section-heading"><div class="tabs"><button data-period="week" class="${metricPeriod === 'week' ? 'active' : ''}">Semana</button><button data-period="month" class="${metricPeriod === 'month' ? 'active' : ''}">Mês civil</button></div><span>${fmt(period.start, { hour: undefined, minute: undefined })} — ${fmt(period.end - 1, { hour: undefined, minute: undefined })}</span></div><div class="stats-grid three">${stat('Candidaturas pendentes', applications, 'Pessoas sem seleção ativa no trabalho', 'neutral')}${stat('Confirmações pendentes', waiting, 'Convocações válidas no período', 'amber')}${stat('Vagas em aberto', slots, 'Vagas por dia futuro no período', 'green')}</div><div class="info-line">Somente freelancers. Sem pontuação ou ordenação automática. Horas somam apenas horários conferidos; trabalhos encerrados ainda não conferidos aparecem na coluna de pendências. Cancelados são excluídos.</div><section class="panel table-scroll"><table><thead><tr><th>Freelancer</th><th>Eventos realizados</th><th>Dias de ação</th><th>Horas conferidas</th><th>Conferências pendentes</th>${actor.role === 'owner' ? '<th>Valores informados</th><th>Sem valor</th>' : ''}</tr></thead><tbody>${rows.map(r => `<tr><td><strong>${esc(r.person.name)}</strong></td><td>${r.events}</td><td>${r.days}</td><td>${r.hours.toLocaleString('pt-BR', { maximumFractionDigits: 1 })}h</td><td>${r.pending}</td>${actor.role === 'owner' ? `<td>${money(r.amount)}</td><td>${r.missing}</td>` : ''}</tr>`).join('')}</tbody></table></section>${actor.role === 'owner' ? '<p class="muted">Valores ausentes não equivalem a zero. A soma dos valores informados não é o custo total dos eventos.</p>' : ''}`;
}
function team() {
  return `<section class="panel detail">${state.people.map(p => `<div class="list-row"><div><strong>${esc(p.name)}</strong><p>${roles[p.role]} · ${p.phone} · ${p.approved ? 'Aprovado' : 'Aguardando aprovação dos donos'}</p></div><div class="button-row">${!p.approved && actor.role === 'owner' ? `<button data-approve="${p.id}">Aprovar cadastro</button>` : ''}${p.role === 'promoter' ? `<select aria-label="Vínculo de ${esc(p.name)}" data-link="${p.id}">${[['unclassified', 'Classificar vínculo'], ['freelancer', 'Freelancer'], ['employee', 'Funcionário'], ['provider', 'Prestador']].map(([v, text]) => `<option value="${v}" ${p.link === v ? 'selected' : ''}>${text}</option>`).join('')}</select>` : ''}<button class="secondary small" data-password="${p.id}">Recuperar acesso</button></div></div>`).join('')}</section>`;
}
function photos() {
  const records = state.records.filter(r => D.canReadPhoto(state, actor, r));
  return `<div class="info-line">Arquivos demonstrativos armazenados neste navegador. A exclusão é simulada ao avançar o relógio ou carregar a aplicação; o histórico é preservado.</div><div class="photo-grid">${records.length ? records.map(r => { const a = D.getAssignment(state, r.assignmentId); return `<article class="panel photo-card"><h3>${esc(eventName(a.eventId))}</h3><p>${esc(personName(a.personId))} · ${fmt(r.planned.start)}</p><div class="photo-pair">${['startPhoto', 'endPhoto'].map((key, i) => { const photo = r[key]; return `<div><span class="photo-label">${i ? 'ENCERRAMENTO' : 'INÍCIO'}</span>${photo?.data ? `<img src="${esc(photo.data)}" alt="Foto ${i ? 'final' : 'inicial'} de demonstração" loading="lazy"><a class="download" href="${esc(photo.data)}" download="${esc(photo.name)}">Baixar foto</a>` : `<div class="photo-missing">${photo?.deletedAt ? 'Arquivo excluído por retenção' : 'Aguardando envio'}</div>`}${photo ? `<small>Envio: ${fmt(photo.sentAt)}</small>` : ''}</div>`; }).join('')}</div><p class="muted">${r.closedAt ? `Retenção até ${fmt(r.closedAt + D.POLICY.retentionDays * D.DAY)}.` : 'Retenção de 30 dias contada a partir do encerramento.'}</p></article>`; }).join('') : empty('Nenhum registro disponível', 'As fotos de suas participações aparecerão aqui.')}</div>`;
}
function history() { return `<section class="panel detail">${state.history.map(h => `<div class="history-row"><div><strong>${esc(h.message)}</strong><p>${fmt(h.at)} · ${esc(h.by)}</p></div></div>`).join('')}</section>`; }
function accounts() {
  modal('Contas fictícias por perfil', `<div class="modal-body"><div class="info-line">Acesso simulado: a troca abaixo não é autenticação segura. Nenhum dado real deve ser inserido.</div><form id="account-form">${field('Entrar como', `<select name="person">${state.people.filter(p => p.approved).map(p => `<option value="${p.id}" ${actor?.id === p.id ? 'selected' : ''}>${roles[p.role]} · ${esc(p.name)}</option>`).join('')}</select>`)}${actions('Usar conta demo')}</form><button class="text-button" data-action="logout">Testar acesso por telefone e senha</button></div>`);
}
function loginScreen() {
  $('#app').innerHTML = `<div class="login-shell"><div class="login-brand"><div class="brand"><img class="brand-logo" src="/src/assets/retratus-dark.png" alt="Retratus"></div><h1>Equipe e escalas</h1><p>Demonstração funcional · Belém, Pará</p></div><section class="login-panel"><h2>Entrar</h2><p class="muted">Somente dados fictícios. Autenticação local simulada, inadequada para produção.</p><form id="login-form">${field('Telefone fictício', input('phone', '00000000001', 'tel', 'required autocomplete="username"'))}${field('Senha demonstrativa', input('password', 'demo123', 'password', 'required autocomplete="current-password"'))}<button type="submit">Entrar na demonstração</button></form><div class="login-help"><button class="text-button" data-action="register">Criar cadastro fictício</button><button class="text-button" data-action="accounts">Ver contas de teste</button><p>Recuperação de acesso pela gestão, sem SMS. Na demo, entre em uma conta da gestão e use Equipe → Recuperar acesso.</p></div></section></div>`;
}
function eventForm(id) {
  const e = id ? D.getEvent(state, id) : { title: '', location: '', city: 'Belém', type: 'event', notes: '', preference: '', days: [{ id: D.uid('day'), date: D.localDate(state.now + 3 * D.DAY), start: '18:00', end: '22:00' }], services: [{ name: 'Totem', capacity: 1 }] };
  modal(id ? 'Editar Evento ou Ação' : 'Novo Evento ou Ação', `<form id="event-form" data-id="${id || ''}" class="modal-body"><div class="form-grid">${field('Nome do Evento ou da Ação', input('title', e.title, 'text', 'required maxlength="120"'), 'full')}${field('Tipo', `<select name="type"><option value="event" ${e.type === 'event' ? 'selected' : ''}>${D.ACTIVITY_TYPES.event}</option><option value="action" ${e.type === 'action' ? 'selected' : ''}>${D.ACTIVITY_TYPES.action}</option></select>`)}${field('Município', input('city', e.city, 'text', 'required maxlength="80"'))}${field('Local', input('location', e.location, 'text', 'required maxlength="160"'), 'full')}</div><h3>Horários diários</h3><p class="muted">Fim anterior ao início representa o dia seguinte. Ações ocupam somente os horários de cada dia; não há candidatura por turnos.</p><div id="event-days">${e.days.map(dayFields).join('')}</div><div class="button-row"><button class="secondary small" type="button" data-action="add-day">Adicionar dia</button><button class="secondary small" type="button" data-action="repeat-days">Repetir até uma data</button></div><h3>Serviços e vagas por dia</h3><div class="service-form">${D.SERVICES.map(s => { const v = e.services.find(v => v.name === s); return `<label class="service-input"><span><input type="checkbox" name="services" value="${s}" ${v ? 'checked' : ''}> ${s}</span><input aria-label="Vagas para ${s}" type="number" min="1" max="30" step="1" name="capacity-${s}" value="${v?.capacity || 1}"></label>`; }).join('')}</div>${field('Observações', `<textarea name="notes" rows="2">${esc(e.notes)}</textarea>`)}${field('Preferência do cliente (somente gestão)', input('preference', e.preference))}${id ? field('Motivo da alteração de escala', input('changeReason', '', 'text', 'placeholder="Obrigatório se mudar dias, horários ou serviços"')) : ''}${id ? '<div class="warning">Mudanças de dias, horários ou serviços retiram as participações futuras ativas e avisam os envolvidos. Dias já iniciados são preservados. Convoque novamente para obter nova confirmação. O histórico anterior será preservado.</div>' : '<p class="muted">O trabalho será criado como rascunho. Revise e publique para abrir a oportunidade.</p>'}${actions(id ? 'Salvar alterações' : 'Criar rascunho')}</form>`);
}
function dayFields(d) { return `<div class="day-fields" data-day-id="${d.id}">${field('Data', input('date', d.date, 'date', 'required'))}${field('Início', input('start', d.start, 'time', 'required'))}${field('Fim', input('end', d.end, 'time', 'required'))}<button type="button" class="icon-button" data-action="remove-day" aria-label="Remover dia">×</button></div>`; }
function inviteForm(eventId, personId = '') {
  const e = D.getEvent(state, eventId), days = e.days.filter(d => D.interval(d).start > state.now);
  modal('Convocar pessoa', `<form id="invite-form" data-id="${eventId}" class="modal-body"><p><strong>${esc(e.title)}</strong></p><div class="info-line">Seleção manual, inclusive sem candidatura. A vaga fica reservada até o prazo de resposta; expiração libera a vaga sem convocar outra pessoa.</div>${field('Pessoa', `<select name="personId" required><option value="">Selecione</option>${state.people.filter(p => p.approved && p.role === 'promoter').map(p => `<option value="${p.id}" ${personId === p.id ? 'selected' : ''}>${esc(p.name)}</option>`).join('')}</select>`)}${field('Serviço', `<select name="service">${e.services.map(s => `<option>${s.name}</option>`).join('')}</select>`)}<h3>Dias da participação</h3><div class="checkbox-list">${days.map(d => `<label><input type="checkbox" name="dayIds" value="${d.id}" checked> ${dateLabel(d.date)} · ${d.start}–${d.end}</label>`).join('') || '<p>Nenhum dia futuro disponível.</p>'}</div>${field('Observação / motivo da convocação', input('reason'))}<p class="muted">Prazo padrão: 24h. Se faltarem menos de 48h, prazo de 2h. Nunca ultrapassa o início da participação.</p>${actions('Registrar convocação')}</form>`);
}
function releaseForm(id) {
  const a = D.getAssignment(state, id);
  modal('Substituição de participação', `<form id="release-form" data-id="${id}" class="modal-body"><p>${esc(personName(a.personId))} · ${esc(eventName(a.eventId))}</p><div class="info-line">Remova os dias necessários e convoque a pessoa substituta manualmente no trabalho. Dias com execução registrada são preservados.</div><div class="checkbox-list">${D.assignmentDays(state, a).map(d => `<label><input type="checkbox" name="dayIds" value="${d.id}"> ${dateLabel(d.date)} · ${d.start}–${d.end}</label>`).join('')}</div>${field('Motivo', input('reason', '', 'text', 'required'))}${actions('Liberar dias selecionados')}</form>`);
}
function applyForm(id) {
  const e = D.getEvent(state, id), previous = state.applications.find(a => a.eventId === id && a.personId === actor.id);
  modal('Manifestar interesse', `<form id="apply-form" data-id="${id}" class="modal-body"><p>${esc(e.title)}</p><p class="muted">Você se candidata ao trabalho e indica serviços de interesse. A gestão escolhe o serviço e a vaga. A candidatura não confirma a participação.</p><div class="checkbox-list">${e.services.map(s => `<label><input type="checkbox" name="services" value="${s.name}" ${previous?.services.includes(s.name) ? 'disabled checked' : ''}> ${s.name}${previous?.services.includes(s.name) ? ' · já registrado' : ''}</label>`).join('')}</div>${actions('Enviar candidatura')}</form>`);
}
function clockForm() { modal('Relógio da demonstração', `<div class="modal-body"><p>Agora: <strong>${fmt(state.now)}</strong> · America/Belem</p><p class="muted">O tempo só avança por este controle. Expirações e retenção são reaplicadas na base local; não há serviço em segundo plano.</p><div class="button-row"><button class="secondary" data-advance="2">＋ 2 horas</button><button class="secondary" data-advance="24">＋ 1 dia</button><button class="secondary" data-advance="744">＋ 31 dias</button></div><form id="clock-form">${field('Avançar para (horário de Belém)', input('time', localInput(state.now), 'datetime-local', 'required'))}${actions('Avançar relógio')}</form><hr><button class="danger-button" data-action="reset">Restaurar demonstração inicial</button><p class="muted">Restaurar remove apenas os dados locais desta demonstração, incluindo fotos e alterações.</p></div>`); }
function localInput(ms) { return new Date(ms - 3 * D.HOUR).toISOString().slice(0, 16); }
function reviewForm(id) {
  const r = state.records.find(r => r.id === id);
  modal('Conferir horários trabalhados', `<form id="review-form" data-id="${id}" class="modal-body"><p class="info-line">Envios originais: ${fmt(r.startPhoto.sentAt)} → ${fmt(r.endPhoto.sentAt)}. Informe os horários trabalhados após a conferência.</p>${field('Início validado · Belém', input('start', localInput(r.validatedStart || r.planned.start), 'datetime-local', 'required'))}${field('Fim validado · Belém', input('end', localInput(r.validatedEnd || r.planned.end), 'datetime-local', 'required'))}${field('Observação da conferência', `<textarea name="note" required>${esc(r.reviewNote)}</textarea>`)}${actions('Salvar conferência')}</form>`);
}
function uploadForm(id, dayId, kind) {
  modal(kind === 'start' ? 'Registrar início' : 'Encerrar participação do dia', `<form id="upload-form" data-id="${id}" data-day="${dayId}" data-kind="${kind}" class="modal-body"><div class="info-line">Use uma imagem fictícia. JPG, PNG ou WebP de até 1 MB. O horário de envio será ${fmt(state.now)}, pelo relógio demonstrativo.</div>${field('Foto de demonstração', '<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required>')}<p>${kind === 'end' ? 'O envio encerra automaticamente somente a sua participação deste dia, deixando-a pendente de conferência e preservando os dias seguintes.' : 'O registro de envio ficará separado do horário previsto e do horário validado pela gestão.'}</p>${actions(kind === 'end' ? 'Enviar e encerrar este dia' : 'Enviar foto de início')}</form>`);
}
document.addEventListener('click', event => {
  const el = event.target.closest('button, a[data-action]'); if (!el) return;
  const d = el.dataset;
  if (d.page) { page = d.page; selectedEvent = null; render(); window.scrollTo(0, 0); }
  else if (d.event) { selectedEvent = d.event; page = actor.role === 'promoter' ? 'opportunities' : 'events'; render(); window.scrollTo(0, 0); }
  else if ('status' in d) { filter.status = d.status; render(); }
  else if (d.period) { metricPeriod = d.period; render(); }
  else if (d.edit) eventForm(d.edit);
  else if (d.invite) inviteForm(d.invite);
  else if (d.candidate) inviteForm(d.eventId, d.candidate);
  else if (d.apply) applyForm(d.apply);
  else if (d.publish) mutate(s => D.publish(s, actor, d.publish), 'Oportunidade publicada para os promotores aprovados.');
  else if (d.respond) mutate(s => D.respond(s, actor, d.respond, d.accept === 'true'), d.accept === 'true' ? 'Participação confirmada.' : 'Convocação recusada.');
  else if (d.release) releaseForm(d.release);
  else if (d.review) reviewForm(d.review);
  else if (d.upload) uploadForm(d.upload, d.day, d.kind);
  else if (d.approve) mutate(s => D.managePerson(s, actor, d.approve, 'approve'), 'Cadastro aprovado.');
  else if (d.password) modal('Recuperação pela gestão', `<form id="password-form" data-id="${d.password}" class="modal-body"><p>${esc(personName(d.password))}. A gestão redefine a senha após verificar a identidade por contato direto. Aqui o procedimento é apenas demonstrativo.</p>${field('Nova senha fictícia', input('password', '', 'password', 'minlength="6" required'))}${actions('Redefinir senha demo')}</form>`);
  else if (d.amount) { const r = state.records.find(r => r.id === d.amount); modal('Valor informado', `<form id="amount-form" data-id="${r.id}" class="modal-body"><p>Visível somente para os donos na interface. Não é confirmação de pagamento nem custo total do evento.</p>${field('Valor informado (R$)', input('amount', r.amount ?? '', 'number', 'min="0" step="0.01" placeholder="Não informado"'))}<p class="muted">Deixe vazio quando não informado. Zero é um valor explícito.</p>${actions()}</form>`); }
  else if (d.cancel) modal('Cancelar trabalho', `<form id="cancel-form" data-id="${d.cancel}" class="modal-body"><p>O histórico será preservado. Trabalhos cancelados não entram nos indicadores de realização.</p>${field('Motivo do cancelamento', '<textarea name="reason" required></textarea>')}${actions('Registrar cancelamento')}</form>`);
  else if (d.advance) { if (mutate(s => { s.now += Number(d.advance) * D.HOUR; D.expire(s); }, 'Relógio avançado. Prazos e retenção reavaliados.')) { close(); } }
  else if (d.action) {
    event.preventDefault();
    switch (d.action) {
      case 'home': page = navItems()[0][0]; selectedEvent = null; render(); break;
      case 'close': close(); break;
      case 'limits': limits(); break;
      case 'accounts': accounts(); break;
      case 'clock': clockForm(); break;
      case 'new-event': eventForm(); break;
      case 'back-events': selectedEvent = null; render(); break;
      case 'logout': close(); actor = null; sessionStorage.removeItem('retratus.actor'); render(); break;
      case 'register': modal('Cadastro demonstrativo', `<form id="register-form" class="modal-body"><p>Use apenas informações fictícias. O cadastro aguardará aprovação de uma conta de dono.</p>${field('Nome fictício', input('name', '', 'text', 'required maxlength="80"'))}${field('Telefone fictício com DDD', input('phone', '', 'tel', 'required pattern="[0-9]{10,11}"'))}${field('Senha fictícia', input('password', '', 'password', 'required minlength="6"'))}${actions('Solicitar cadastro')}</form>`); break;
      case 'add-day': { const last = $('#event-days').lastElementChild; const date = last?.querySelector('[name=date]').value || D.localDate(state.now); $('#event-days').insertAdjacentHTML('beforeend', dayFields({ id: D.uid('day'), date: D.localDate(Date.parse(date + 'T12:00:00-03:00') + D.DAY), start: last?.querySelector('[name=start]').value || '18:00', end: last?.querySelector('[name=end]').value || '22:00' })); break; }
      case 'remove-day': if ($('#event-days').children.length > 1) el.closest('.day-fields').remove(); else toast('Mantenha pelo menos um dia.', true); break;
      case 'repeat-days': { const holder = document.createElement('div'); holder.className = 'repeat-controls'; holder.innerHTML = '<label>Repetir último horário até <input type="date" id="repeat-until"></label><button type="button" class="secondary small" data-action="fill-days">Aplicar</button>'; if (!$('.repeat-controls')) el.parentElement.after(holder); break; }
      case 'fill-days': { const last = $('#event-days').lastElementChild; const from = Date.parse(last.querySelector('[name=date]').value + 'T12:00:00-03:00'), to = Date.parse($('#repeat-until').value + 'T12:00:00-03:00'); if (!Number.isFinite(to) || to <= from || to - from > 100 * D.DAY) { toast('Escolha uma data posterior, até 100 dias.', true); break; } for (let at = from + D.DAY; at <= to; at += D.DAY) $('#event-days').insertAdjacentHTML('beforeend', dayFields({ id: D.uid('day'), date: D.localDate(at), start: last.querySelector('[name=start]').value, end: last.querySelector('[name=end]').value })); $('.repeat-controls').remove(); break; }
      case 'reset': modal('Restaurar base fictícia?', '<div class="modal-body"><p>Suas alterações e fotos locais serão removidas. A base fictícia inicial será recriada.</p><div class="button-row"><button class="secondary" data-action="close">Voltar</button><button class="danger-button" data-action="confirm-reset">Restaurar dados demo</button></div></div>'); break;
      case 'confirm-reset': try { state = Repo.reset(); actor = state.people[0]; sessionStorage.setItem('retratus.actor', actor.id); selectedEvent = null; filter = { from: '2026-11-18', to: '2026-11-18', start: '00:00', end: '23:59', person: '', status: '' }; close(); render(); toast('Demonstração restaurada.'); } catch (error) { toast(error.message, true); } break;
    }
  }
});
document.addEventListener('change', event => { if (event.target.dataset.link) mutate(s => D.managePerson(s, actor, event.target.dataset.link, 'link', event.target.value)); });
document.addEventListener('submit', async event => {
  event.preventDefault(); const form = event.target, data = new FormData(form), values = Object.fromEntries(data), id = form.dataset.id;
  try {
    let success = false;
    switch (form.id) {
      case 'filter-form': { const next = { ...filter, ...values }; const start = Date.parse(`${next.from}T${next.start}:00-03:00`), end = Date.parse(`${next.to}T${next.end}:59-03:00`); if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) throw Error('Informe um período válido, com fim após o início.'); filter = next; render(); return; }
      case 'account-form': actor = state.people.find(p => p.id === values.person && p.approved); sessionStorage.setItem('retratus.actor', actor.id); page = navItems()[0][0]; selectedEvent = null; close(); render(); toast('Conta alterada.'); return;
      case 'login-form': { const p = state.people.find(p => p.phone === values.phone.replace(/\D/g, '') && p.password === values.password); if (!p) throw Error('Telefone ou senha fictícia inválidos.'); if (!p.approved) throw Error('Seu cadastro aguarda aprovação dos donos.'); actor = p; sessionStorage.setItem('retratus.actor', p.id); selectedEvent = null; page = navItems()[0][0]; render(); return; }
      case 'register-form': success = mutate(s => D.register(s, values), 'Cadastro fictício registrado. Aguarde aprovação de uma conta de dono.'); break;
      case 'invite-form': success = mutate(s => D.invite(s, actor, { eventId: id, ...values, dayIds: data.getAll('dayIds') }), 'Convocação registrada. Aguardando resposta da pessoa.'); break;
      case 'apply-form': success = mutate(s => D.apply(s, actor, id, data.getAll('services')), 'Interesse registrado. A seleção será feita manualmente.'); break;
      case 'release-form': success = mutate(s => D.release(s, actor, id, data.getAll('dayIds'), values.reason), 'Dias liberados. Convoque o substituto manualmente no trabalho.'); break;
      case 'cancel-form': success = mutate(s => D.cancelEvent(s, actor, id, values.reason)); break;
      case 'password-form': success = mutate(s => D.managePerson(s, actor, id, 'password', values.password)); break;
      case 'amount-form': success = mutate(s => D.setAmount(s, actor, id, values.amount === '' ? null : Number(values.amount))); break;
      case 'review-form': success = mutate(s => D.reviewRecord(s, actor, id, Date.parse(values.start + ':00-03:00'), Date.parse(values.end + ':00-03:00'), values.note)); break;
      case 'clock-form': { const at = Date.parse(values.time + ':00-03:00'); if (!Number.isFinite(at) || at <= state.now) throw Error('O relógio só avança. Para voltar ao início, restaure a demonstração.'); success = mutate(s => { s.now = at; D.expire(s); }, 'Relógio avançado. Prazos e retenção reavaliados.'); break; }
      case 'event-form': { const days = [...form.querySelectorAll('.day-fields')].map(row => ({ id: row.dataset.dayId, date: row.querySelector('[name=date]').value, start: row.querySelector('[name=start]').value, end: row.querySelector('[name=end]').value })).sort((a, b) => a.date.localeCompare(b.date)); const services = data.getAll('services').map(name => ({ name, capacity: Number(data.get('capacity-' + name)) })); const value = { title: values.title, city: values.city, location: values.location, type: values.type, notes: values.notes, preference: values.preference, changeReason: values.changeReason, days, services }; let newId; success = mutate(s => { newId = D.saveEvent(s, actor, value, id || undefined).id; }, id ? 'Trabalho atualizado. Consulte eventuais participações que precisam de nova convocação.' : 'Rascunho criado. Revise e publique o trabalho.'); if (success) { selectedEvent = newId; page = 'events'; render(); } break; }
      case 'upload-form': { const file = data.get('photo'); if (!file?.size || file.size > D.POLICY.photoBytes || !['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) throw Error('Escolha JPG, PNG ou WebP com até 1 MB.'); const submit = form.querySelector('[type=submit]'); submit.disabled = true; submit.textContent = 'Validando imagem…'; try { const bitmap = await createImageBitmap(file); if (bitmap.width > 12000 || bitmap.height > 12000 || bitmap.width * bitmap.height > 36000000) { bitmap.close(); throw Error('Imagem muito grande. Reduza para até 36 megapixels e 12.000 pixels por lado.'); } bitmap.close(); const content = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = () => reject(Error('Não foi possível ler a imagem.')); reader.readAsDataURL(file); }); success = mutate(s => D.uploadPhoto(s, actor, id, form.dataset.day, form.dataset.kind, { name: file.name, size: file.size, data: content }), form.dataset.kind === 'end' ? 'Participação do dia encerrada. Pendente de conferência.' : 'Foto de início registrada.'); } finally { submit.disabled = false; submit.textContent = form.dataset.kind === 'end' ? 'Enviar e encerrar este dia' : 'Enviar foto de início'; } break; }
    }
    if (success) close();
  } catch (error) { toast(error.message || 'Não foi possível concluir a operação.', true); }
});
window.addEventListener('storage', event => { if (event.key === 'retratus.demo.v1') { try { state = Repo.load(); actor = state.people.find(p => p.id === actor?.id && p.approved) || null; close(); render(); toast('A demonstração foi atualizada por outra aba.'); } catch (error) { toast(error.message, true); } } });
if (state) render();
